1	package watcher
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"time"
8	
9		"github.com/gravitational/teleport/api/client"
10		"github.com/gravitational/teleport/api/types"
11		"github.com/immuta/operations/services/televibe/internal/evaluator"
12	)
13	
14	const reconnectDelay = 5 * time.Second
15	
16	// Watcher streams pending Teleport access requests onto a channel.
17	// It reconnects automatically on watcher failure.
18	type Watcher struct {
19		client   *client.Client
20		requests chan evaluator.Request
21		logger   *slog.Logger
22	}
23	
24	func New(ctx context.Context, addr, identityFile string, logger *slog.Logger) (*Watcher, error) {
25		clt, err := client.New(ctx, client.Config{
26			Addrs: []string{addr},
27			Credentials: []client.Credentials{
28				client.LoadIdentityFile(identityFile),
29			},
30		})
31		if err != nil {
32			return nil, fmt.Errorf("connecting to teleport: %w", err)
33		}
34	
35		w := &Watcher{
36			client:   clt,
37			requests: make(chan evaluator.Request, 32),
38			logger:   logger,
39		}
40	
41		go w.watch(ctx)
42		return w, nil
43	}
44	
45	// Requests returns the channel of incoming pending access requests.
46	func (w *Watcher) Requests() <-chan evaluator.Request {
47		return w.requests
48	}
49	
50	// Close shuts down the Teleport client.
51	func (w *Watcher) Close() {
52		w.client.Close()
53	}
54	
55	func (w *Watcher) watch(ctx context.Context) {
56		defer close(w.requests)
57	
58		for {
59			if err := w.watchOnce(ctx); err != nil {
60				if ctx.Err() != nil {
61					return
62				}
63				w.logger.Error("watcher disconnected, reconnecting", "error", err, "delay", reconnectDelay)
64				select {
65				case <-time.After(reconnectDelay):
66				case <-ctx.Done():
67					return
68				}
69			}
70		}
71	}
72	
73	func (w *Watcher) watchOnce(ctx context.Context) error {
74		watcher, err := w.client.NewWatcher(ctx, types.Watch{
75			Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
76		})
77		if err != nil {
78			return fmt.Errorf("creating watcher: %w", err)
79		}
80		defer watcher.Close()
81	
82		// The first event must be OpInit confirming the watch is established.
83		select {
84		case event := <-watcher.Events():
85			if event.Type != types.OpInit {
86				return fmt.Errorf("expected OpInit, got %v", event.Type)
87			}
88			w.logger.Info("teleport watcher initialized")
89		case <-watcher.Done():
90			return fmt.Errorf("watcher closed during init: %w", watcher.Error())
91		case <-ctx.Done():
92			return ctx.Err()
93		}
94	
95		for {
96			select {
97			case event := <-watcher.Events():
98				if event.Type != types.OpPut {
99					continue
100				}
101				req, ok := event.Resource.(types.AccessRequest)
102				if !ok {
103					continue
104				}
105				// Only forward newly-pending requests; ignore state transitions (approve/deny).
106				if req.GetState() != types.RequestState_PENDING {
107					continue
108				}
109				select {
110				case w.requests <- toRequest(req):
111				case <-ctx.Done():
112					return ctx.Err()
113				}
114			case <-watcher.Done():
115				return fmt.Errorf("watcher closed: %w", watcher.Error())
116			case <-ctx.Done():
117				return ctx.Err()
118			}
119		}
120	}
121	
122	func toRequest(req types.AccessRequest) evaluator.Request {
123		return evaluator.Request{
124			ID:     req.GetName(),
125			User:   req.GetUser(),
126			Roles:  req.GetRoles(),
127			Reason: req.GetRequestReason(),
128		}
129	}
